def signature(kind):
    """Canonical tuple signature; fixed-array input signatures are explicit below."""
    if isinstance(kind, Array):
        return signature(kind.item) + '[]'
    return '(' + ','.join(signature(k) for k in kind) + ')' if isinstance(kind, tuple) else kind


