def _witness_type(name):
    if name.endswith('[]'):
        return Array(_witness_type(name[:-2]), MAX_WITNESS_ROWS)
    fixed = re.fullmatch(r'(.+)\[([0-9]+)\]', name)
    if fixed:
        return (_witness_type(fixed[1]),) * int(fixed[2])
    if name in WITNESS_LAYOUTS:
        return tuple(_witness_type(field.split()[0]) for field in WITNESS_LAYOUTS[name].split(';'))
    return name


