def definitions():
    """Complete ordered native definition stage, without selected-version extras."""
    from . import view_preservation_snapshot_types_v1 as snapshot
    from . import view_preservation_reference_types_v1 as reference
    from .view_preservation_output_wire_v1 import definitions as output_definitions
    from .view_policy_adoption_wire_v2 import RAW_DEFINITION_BYTES, V2_PAYLOAD_SCHEMA_BYTES, MANIFEST_SCHEMA_BYTES
    rows = list(_COMMON_DEFINITIONS)
    rows.extend((r['name'], r['kind'], r['bytes']) for r in reference.definitions()[3:])
    rows.append(('RAW_BYTES', 1, RAW_DEFINITION_BYTES))
    rows.extend((name, kind, value) for name, kind, value in (
        ('STREAM_VIEW_PRESERVATION_SNAPSHOT_ABI_V1', 0, snapshot.SNAPSHOT_SCHEMA_BYTES),
        ('STREAM_VIEW_PRESERVATION_SNAPSHOT_PROFILE_V1', 2, snapshot.SNAPSHOT_PROFILE_BYTES),
        ('STREAM_ABI_VIEW_PRESERVATION_SNAPSHOT_V1', 1, snapshot.SNAPSHOT_CANON_BYTES)))
    rows.extend((r['name'], r['kind'], r['bytes']) for r in reference.definitions()[:3])
    rows.extend((name, kind, value) for name, kind, value in (
        ('STREAM_VIEW_PRESERVATION_CONTENT_ROOT_V1', 0, snapshot.ROOT_SCHEMA_BYTES),
        ('STREAM_ABI_VIEW_PRESERVATION_CONTENT_ROOT_V1', 1, snapshot.ROOT_CANON_BYTES)))
    rows.extend((r['name'], r['kind'], r['bytes']) for r in output_definitions())
    rows.extend((name, 0, value) for name, value in (
        ('STREAM_STATIC_POLICY_VIEW_PAYLOAD_V2', V2_PAYLOAD_SCHEMA_BYTES),
        ('STREAM_COLLECTION_VIEW_MANIFEST_ABI_V1', MANIFEST_SCHEMA_BYTES)))
    return tuple({'name': name, 'id': schema_id(name), 'kind': kind,
                  'hash': keccak256(value), 'bytes': value} for name, kind, value in rows)
